package io.github.dream07code.innovationspace.scoring;
import org.springframework.boot.context.properties.ConfigurationProperties;
@ConfigurationProperties("app.ai") public class ScoringProperties {private boolean enabled;private String provider="disabled",baseUrl,apiKey,model;private int connectTimeoutMs=3000,requestTimeoutMs=30000,maxRetries=2,maxConcurrency=2;
 public boolean isEnabled(){return enabled;}public void setEnabled(boolean v){enabled=v;}public String getProvider(){return provider;}public void setProvider(String v){provider=v;}public String getBaseUrl(){return baseUrl;}public void setBaseUrl(String v){baseUrl=v;}public String getApiKey(){return apiKey;}public void setApiKey(String v){apiKey=v;}public String getModel(){return model;}public void setModel(String v){model=v;}public int getConnectTimeoutMs(){return connectTimeoutMs;}public void setConnectTimeoutMs(int v){connectTimeoutMs=v;}public int getRequestTimeoutMs(){return requestTimeoutMs;}public void setRequestTimeoutMs(int v){requestTimeoutMs=v;}public int getMaxRetries(){return maxRetries;}public void setMaxRetries(int v){maxRetries=v;}public int getMaxConcurrency(){return maxConcurrency;}public void setMaxConcurrency(int v){maxConcurrency=v;}
 public void validate(){if(!enabled)return;if(provider==null||provider.isBlank()||model==null||model.isBlank()||apiKey==null||apiKey.isBlank())throw new IllegalArgumentException("AI provider configuration is incomplete");if(!"mock".equals(provider)){if(baseUrl==null||baseUrl.isBlank())throw new IllegalArgumentException("AI base URL is required");var uri=java.net.URI.create(baseUrl);if(!"https".equalsIgnoreCase(uri.getScheme())&&!"localhost".equalsIgnoreCase(uri.getHost())&&!"127.0.0.1".equals(uri.getHost()))throw new IllegalArgumentException("AI base URL must use HTTPS");}if(connectTimeoutMs<100||requestTimeoutMs<1000||maxRetries<0||maxRetries>3||maxConcurrency<1)throw new IllegalArgumentException("Invalid AI timeout/retry configuration");}
 @Override public String toString(){return "ScoringProperties[enabled="+enabled+",provider="+provider+",baseUrl=<redacted>,apiKey=<redacted>,model="+model+"]";}}
